CREATE OR REPLACE FUNCTION get_plant_age(p_sitekey text)
RETURNS integer AS $$
DECLARE
    v_goliveon date;
BEGIN
    SELECT goliveon INTO v_goliveon FROM plants WHERE sitekey = p_sitekey;
    RETURN EXTRACT(DAY FROM AGE(CURRENT_DATE, v_goliveon))::integer;
END;
$$ LANGUAGE plpgsql;

